EMPTY_CELL = ' '
PLAYER_X = 'X'
PLAYER_O = 'O'


class TicTacToe:
    def __init__(self, N=3):
        self._board = [[' ' for _ in range(N)] for _ in range(3)]
        self._current_player = PLAYER_X

    @property
    def board(self):
        return [row[:] for row in self._board]

    @board.setter
    def board(self, value):
        self._board = [row[:] for row in value]

    @property
    def current_player(self):
        return self._current_player

    @current_player.setter
    def current_player(self, value):
        if value not in (PLAYER_X, PLAYER_O):
            raise ValueError("Current player must be X or O")
        self._current_player = value

    def make_move(self, row, col):
        if self._is_cell_available(row, col):
            self._place_player(row, col)
            return True
        return False

    def _is_cell_available(self, row, col):
        return self._board[row][col] == EMPTY_CELL

    def _place_player(self, row, col):
        self._board[row][col] = self._current_player
        self._switch_player()

    def _switch_player(self):
        self._current_player = PLAYER_O if self._current_player == PLAYER_X else PLAYER_X

    def check_winner(self):
        row_winner = self._check_rows_for_winner()
        if row_winner is not None:
            return row_winner

        col_winner = self._check_columns_for_winner()
        if col_winner is not None:
            return col_winner

        diag_winner = self._check_diagonals_for_winner()
        if diag_winner is not None:
            return diag_winner

        return None

    def _check_rows_for_winner(self):
        for row in self._board:
            if self._is_all_and_not_empty(row):
                return row[0]
        return None

    def _check_columns_for_winner(self):
        for col in range(3):
            if self._is_column_won(col):
                return self._board[0][col]
        return None

    def _is_column_won(self, col):
        return (
            self._board[0][col] == self._board[1][col]
            == self._board[2][col]
            and self._board[0][col] != EMPTY_CELL
        )

    def _check_diagonals_for_winner(self):
        if self._is_main_diagonal_won():
            return self._board[0][0]
        if self._is_anti_diagonal_won():
            return self._board[0][2]
        return None

    def _is_main_diagonal_won(self):
        return (
            self._board[0][0] == self._board[1][1]
            == self._board[2][2]
            and self._board[0][0] != EMPTY_CELL
        )

    def _is_anti_diagonal_won(self):
        return (
            self._board[0][2] == self._board[1][1]
            == self._board[2][0]
            and self._board[0][2] != EMPTY_CELL
        )

    def _is_all_and_not_empty(self, row):
        return len(row) == 3 and row[0] == row[1] == row[2] and row[0] != EMPTY_CELL

    def is_board_full(self):
        return not any(EMPTY_CELL in row for row in self._board)
